456	        Claim claim = claim(sheetId, claimId);
457	        if (!roles.permits(sheetId, user, "reassign")) {
458	            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "Your role may not reassign a claim.");
459	        }
460	        if (claim.getStatus() != ClaimStatus.DRAFT && !claim.getStatus().isOpen()) {
461	            throw new ResponseStatusException(HttpStatus.CONFLICT,
462	                    "A " + claim.getStatus() + " claim cannot be reassigned.");
463	        }
464	        periods.refuseIfClosed(sheetId, claim.getDate());
465	        Person from = person(sheetId, claim.getPersonId());
466	        Person to = person(sheetId, personId);
467	        if (from.getId().equals(to.getId())) {
468	            throw new ResponseStatusException(HttpStatus.CONFLICT, "The claim is already " + to.getName() + "'s.");
469	        }
470	        refuseIfRetired(to, claim.getDate());
471	        refuseUnlessCorrects(sheetId, personId, claim.getAmount(), claim.getCorrects());
472	        claim.reassign(to.getId());
473	        claim.unbind();
474	        Claim saved = claims.saveAndFlush(claim);
475	        audited("CLAIM_REASSIGNED", sheetId, user, to, saved, saved.getNumber(),
476	                " from=" + from.getName() + " to=" + to.getName());
477	        rollups.audit(sheetId, user, before);
478	        return saved;
479	    }
480	
481	    /** What a split did: the original claim, as it is now, and the new claim split off it. */
482	    public record Split(Claim original, Claim split) {
483	    }
484	
485	    /**
486	     * Split an amount (above 0.00 and below the claim's amount) off an OPEN claim: it keeps the rest
487	     * of its amount and loses any figure a statement bound it to; a new OPEN claim with the split-off
488	     * amount, the same date and note, the next number, opened by the user and due by a date fixed now
489	     * from the terms in force on its date, names the original's number as the one it was split from.
490	     * Refused when the claim is not OPEN, is deferred on the sheet's today, or is dated inside a
491	     * closed period.
492	     */
493	    @Transactional
494	    public Split split(String sheetId, String user, long claimId, BigDecimal amount) {
495	        Sheet sheet = sheets.lock(sheetId);
496	        LocalDate today = sheet.getToday();
497	        Rollups.Rollup before = rollups.take(sheetId);
498	        Claim claim = claim(sheetId, claimId);
499	        if (claim.getStatus() != ClaimStatus.OPEN) {
500	            throw new ResponseStatusException(HttpStatus.CONFLICT,
501	                    "A " + claim.getStatus() + " claim cannot be split; only an OPEN one can.");
502	        }
503	        if (claim.isDeferredOn(today)) {
504	            throw new ResponseStatusException(HttpStatus.CONFLICT,
505	                    "The claim is deferred until " + claim.getDeferredUntil() + ": it cannot be split.");
506	        }
507	        periods.refuseIfClosed(sheetId, claim.getDate());
508	        BigDecimal off = money(amount);
509	        if (off.signum() <= 0 || off.compareTo(claim.getAmount()) >= 0) {
510	            throw new ResponseStatusException(HttpStatus.CONFLICT,
511	                    "The amount split off must be above 0.00 and below the claim's " + claim.getAmount().toPlainString() + ".");
512	        }
513	        Person person = person(sheetId, claim.getPersonId());
514	        LocalDate dueBy = claim.getDate().plusDays(sheet.termsFor(person.gradeOn(claim.getDate()), claim.getDate()));
515	        Claim split = claim.split(off, dueBy);
516	        split.number(periods.nextClaimNumber(sheetId, split.getDate()));
517	        split.openedBy(user);
518	        Claim original = claims.saveAndFlush(claim);
519	        split = logged(claims.saveAndFlush(split), user, person);
520	        audited("CLAIM_SPLIT", sheetId, user, person, original, original.getNumber(), " into=" + split.getNumber());
521	        audited("CLAIM_OPENED", sheetId, user, person, split);
522	        rollups.audit(sheetId, user, before);
523	        return new Split(original, split);
524	    }
525	
526	    /**
527	     * The PENDING claim a steward approves or rejects; refused when it is not PENDING, when its date
528	     * is inside a closed period, or when the user is not a steward.
529	     */
530	    private Claim pending(String sheetId, String user, long claimId) {
531	        Claim claim = claim(sheetId, claimId);
532	        periods.refuseIfClosed(sheetId, claim.getDate());
533	        if (claim.getStatus() != ClaimStatus.PENDING) {
534	            throw new ResponseStatusException(HttpStatus.CONFLICT,
535	                    "A " + claim.getStatus() + " claim is not pending approval.");
536	        }
537	        if (!Role.STEWARD.equals(roles.roleOf(sheetId, user))) {
538	            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "Only a steward approves or rejects a claim.");
539	        }
540	        return claim;
541	    }
542	
543	    /**
544	     * Refuse settling or approving a claim with no proofs whose due is above the sheet's proof threshold
545	     * in force on the claim's date (a due of n/a is within any threshold).
546	     */
547	    private void refuseUnproved(String sheetId, Claim claim, BigDecimal due) {
548	        BigDecimal threshold = sheets.load(sheetId).proofThresholdOn(claim.getDate());
549	        if (claim.getProofs() == 0 && threshold != null && due != null && due.compareTo(threshold) > 0) {
550	            throw new ResponseStatusException(HttpStatus.CONFLICT,
551	                    "The claim's due is above the proof threshold of " + threshold.toPlainString()
552	                            + ": it needs a proof before it is settled.");
553	        }
554	    }
555	
556	    /** Whether a clerk is settling a claim whose due is above the sheet's clerk limit. */
557	    private boolean overClerkLimit(String sheetId, String user, BigDecimal due) {
558	        BigDecimal limit = sheets.clerkLimit(sheetId);
559	        if (limit == null || due == null || due.compareTo(limit) <= 0) {
560	            return false;
561	        }
562	        return Role.CLERK.equals(roles.roleOf(sheetId, user));
563	    }
564	
565	    /**
566	     * Refuse a correction (an amount below 0.00) unless it names, by number, a SETTLED claim of the
567	     * same person; and refuse naming a claim to correct on any other claim.
568	     */
569	    private void refuseUnlessCorrects(String sheetId, long personId, BigDecimal amount, String corrects) {
570	        if (amount.signum() >= 0) {
571	            if (corrects != null) {
572	                throw new ResponseStatusException(HttpStatus.CONFLICT,
573	                        "Only a correction, with an amount below 0.00, names a claim it corrects.");
574	            }
575	            return;
576	        }
577	        boolean settled = corrects != null && claims.findBySheetIdAndPersonIdAndNumber(sheetId, personId, corrects)
578	                .filter(corrected -> corrected.getStatus() == ClaimStatus.SETTLED)
579	                .isPresent();
580	        if (!settled) {
581	            throw new ResponseStatusException(HttpStatus.CONFLICT,
582	                    "A correction must name the number of a SETTLED claim of the same person.");
583	        }
584	    }
585	
586	    /** Refuse a claim dated after its person's retirement. */
587	    private static void refuseIfRetired(Person person, LocalDate date) {
588	        if (!person.canClaimOn(date)) {
589	            throw new ResponseStatusException(HttpStatus.CONFLICT,
590	                    person.getName() + " is retired from " + person.getRetiredFrom() + ": a claim cannot be dated after it.");
591	        }
592	    }
593	
594	    private Claim claim(String sheetId, long claimId) {
595	        return claims.findByIdAndSheetId(claimId, sheetId)
596	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim on this sheet."));
597	    }
598	
599	    private Person person(String sheetId, long personId) {
600	        return people.findByIdAndSheetId(personId, sheetId)
601	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person on this sheet."));
602	    }
603	
604	    /**
605	     * Add a line to the claim's status log for the status it now has: by the user, on the sheet's
606	     * today, with its due as computed now.
607	     */
608	    private Claim logged(Claim claim, String user, Person person) {
609	        claim.logged(user, sheets.today(claim.getSheetId()), dues.due(claim, person.gradeOn(claim.getDate())));
610	        return claims.saveAndFlush(claim);
611	    }
612	
613	    /** Record the change to the claim once it is committed; a claim with a number carries it. */
614	    private void audited(String event, String sheetId, String user, Person person, Claim claim) {
615	        audited(event, sheetId, user, person, claim, claim.getNumber(), "");
616	    }
617	
618	    private void audited(String event, String sheetId, String user, Person person, Claim claim, String number,
619	            String suffix) {
620	        audit.recordOnCommit(event + " sheet=" + sheetId + " by=" + user + " person=" + person.getName()
621	                + " amount=" + claim.getAmount().toPlainString() + " date=" + claim.getDate()
622	                + (number != null ? " number=" + number : "") + suffix);
623	    }
624	
625	    /** The due figure a claim shows, without its late charge (see {@link Dues#figure}). */
626	    public BigDecimal figure(Claim claim, String grade) {
627	        return dues.figure(claim, grade);
628	    }
629	
630	    /** The due a claim shows, with its late charge (see {@link Dues#due}). */
631	    public BigDecimal due(Claim claim, String grade) {
632	        return dues.due(claim, grade);
633	    }
634	
635	    private static BigDecimal money(BigDecimal amount) {
636	        return amount.setScale(2, RoundingMode.UNNECESSARY);
637	    }
638	
639	    private static String clean(String note) {
640	        return note == null ? "" : note.trim();
641	    }
642	}
643	package net.officefloor.hq.app.role;
