645	import jakarta.servlet.http.HttpServletRequest;
646	import jakarta.servlet.http.HttpServletResponse;
647	import java.util.Map;
648	import net.officefloor.hq.app.SignedIn;
649	import org.springframework.context.annotation.Configuration;
650	import org.springframework.http.HttpMethod;
651	import org.springframework.http.HttpStatus;
652	import org.springframework.web.server.ResponseStatusException;
653	import org.springframework.web.servlet.HandlerInterceptor;
654	import org.springframework.web.servlet.HandlerMapping;
655	import org.springframework.web.servlet.config.annotation.InterceptorRegistry;
656	import org.springframework.web.servlet.config.annotation.WebMvcConfigurer;
657	
658	/**
659	 * Refuse every change a viewer asks for on a sheet: any request other than a read, or the loading
660	 * of the sheet, is turned away before it reaches its handler, so it writes nothing and audits nothing.
661	 * A bulk move is the exception: it reaches its handler, which refuses each claim a viewer selected.
662	 */
663	@Configuration
664	public class ViewerGuard implements WebMvcConfigurer, HandlerInterceptor {
665	
666	    private final RoleService roles;
667	
668	    public ViewerGuard(RoleService roles) {
669	        this.roles = roles;
670	    }
671	
672	    @Override
673	    public void addInterceptors(InterceptorRegistry registry) {
674	        // A bulk move answers how many claims it refused, so a viewer's is let through and refuses each.
675	        registry.addInterceptor(this).addPathPatterns("/api/sheets/*/**").excludePathPatterns("/api/sheets/*/load",
676	                "/api/sheets/*/claims/open", "/api/sheets/*/claims/settle");
677	    }
678	
679	    @Override
680	    public boolean preHandle(HttpServletRequest request, HttpServletResponse response, Object handler) {
681	        if (HttpMethod.GET.matches(request.getMethod()) || HttpMethod.HEAD.matches(request.getMethod())) {
682	            return true;
683	        }
684	        String header = request.getHeader(SignedIn.HEADER);
685	        Object variables = request.getAttribute(HandlerMapping.URI_TEMPLATE_VARIABLES_ATTRIBUTE);
686	        if (header == null || !(variables instanceof Map<?, ?> vars)) {
687	            return true;
688	        }
689	        Object sheetId = vars.containsKey("sheetId") ? vars.get("sheetId") : vars.get("id");
690	        if (sheetId instanceof String id && Role.VIEWER.equals(roles.roleOf(id, SignedIn.name(header)))) {
691	            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "A viewer may not change anything on the sheet.");
692	        }
693	        return true;
694	    }
695	}
